  if (kind === "MUSIC" || kind === "AUDIO" || value.includes("audio")) {
    return "AUDIO";
  }
  if (kind === "EVENT" || value.includes("trigger")) return "TRIGGER";
  if (value.includes("hero") || value.includes("player")) return "PLAYER";
